solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <optional>
#include <vector>

struct PcapInfo { bool bigEndian; bool nanoseconds; std::uint32_t snapLength; std::uint32_t linkType; };
struct PcapPacket { std::uint32_t seconds; std::uint32_t fraction; std::uint32_t originalLength; std::vector<std::uint8_t> data; };

namespace
{
    std::uint32_t read32(const std::vector<std::uint8_t>& b, std::size_t i, bool big)
    {
        if (big)
            return (std::uint32_t{ b[i] } << 24) | (std::uint32_t{ b[i + 1] } << 16) | (std::uint32_t{ b[i + 2] } << 8) | b[i + 3];
        return (std::uint32_t{ b[i + 3] } << 24) | (std::uint32_t{ b[i + 2] } << 16) | (std::uint32_t{ b[i + 1] } << 8) | b[i];
    }

    std::uint16_t read16(const std::vector<std::uint8_t>& b, std::size_t i, bool big)
    {
        return static_cast<std::uint16_t>(big ? (b[i] << 8) | b[i + 1] : (b[i + 1] << 8) | b[i]);
    }
}

std::optional<PcapInfo> readHeader(const std::vector<std::uint8_t>& file)
{
    if (file.size() < 24) return std::nullopt;
    PcapInfo info{};
    switch (read32(file, 0, false))
    {
    case 0xA1B2C3D4: break;
    case 0xA1B23C4D: info.nanoseconds = true; break;
    case 0xD4C3B2A1: info.bigEndian = true; break;
    case 0x4D3CB2A1: info.bigEndian = true; info.nanoseconds = true; break;
    default: return std::nullopt;
    }
    if (read16(file, 4, info.bigEndian) != 2) return std::nullopt;
    info.snapLength = read32(file, 16, info.bigEndian);
    info.linkType = read32(file, 20, info.bigEndian);
    return info;
}

std::optional<std::vector<PcapPacket>> readPackets(const std::vector<std::uint8_t>& file)
{
    const auto info{ readHeader(file) };
    if (!info) return std::nullopt;
    const bool big{ info->bigEndian };
    std::vector<PcapPacket> packets;
    std::size_t at{ 24 };
    while (at < file.size())
    {
        if (file.size() - at < 16) return std::nullopt;
        PcapPacket p{};
        p.seconds = read32(file, at, big);
        p.fraction = read32(file, at + 4, big);
        const std::uint32_t captured{ read32(file, at + 8, big) };
        p.originalLength = read32(file, at + 12, big);
        if (captured > info->snapLength || captured > p.originalLength) return std::nullopt;
        at += 16;
        if (file.size() - at < captured) return std::nullopt;
        const auto first{ file.begin() + static_cast<std::ptrdiff_t>(at) };
        p.data.assign(first, first + static_cast<std::ptrdiff_t>(captured));
        at += captured;
        packets.push_back(std::move(p));
    }
    return packets;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
void put32(Bytes& b, std::uint32_t v, bool big) {
    for (int i{ 0 }; i < 4; ++i) b.push_back(static_cast<std::uint8_t>(v >> (big ? 24 - 8 * i : 8 * i)));
}
void put16(Bytes& b, std::uint16_t v, bool big) {
    b.push_back(static_cast<std::uint8_t>(big ? v >> 8 : v));
    b.push_back(static_cast<std::uint8_t>(big ? v : v >> 8));
}
Bytes pcapFile(bool big, std::uint32_t magic, std::uint32_t snap) {
    Bytes f;
    put32(f, magic, big); put16(f, 2, big); put16(f, 4, big);
    put32(f, 0, big); put32(f, 0, big); put32(f, snap, big); put32(f, 1, big);
    return f;
}
void addRecord(Bytes& f, bool big, std::uint32_t sec, std::uint32_t frac, const Bytes& data, std::uint32_t original) {
    put32(f, sec, big); put32(f, frac, big);
    put32(f, static_cast<std::uint32_t>(data.size()), big); put32(f, original, big);
    f.insert(f.end(), data.begin(), data.end());
}
TEST("the global header in both byte orders") {
    const auto le{ readHeader(pcapFile(false, 0xA1B2C3D4, 65535)) };
    CHECK(le.has_value());
    if (le) { CHECK(!le->bigEndian); CHECK(!le->nanoseconds); CHECK_EQ(le->snapLength, 65535u); CHECK_EQ(le->linkType, 1u); }
    const auto be{ readHeader(pcapFile(true, 0xA1B2C3D4, 262144)) };
    CHECK(be.has_value());
    if (be) { CHECK(be->bigEndian); CHECK(!be->nanoseconds); CHECK_EQ(be->snapLength, 262144u); }
    const auto nano{ readHeader(pcapFile(false, 0xA1B23C4D, 100)) };
    CHECK(nano.has_value() && nano->nanoseconds && !nano->bigEndian);
    const auto bigNano{ readHeader(pcapFile(true, 0xA1B23C4D, 100)) };
    CHECK(bigNano.has_value() && bigNano->nanoseconds && bigNano->bigEndian);
}
TEST("bad headers") {
    CHECK(!readHeader(pcapFile(false, 0x12345678, 100)).has_value());
    Bytes f{ pcapFile(false, 0xA1B2C3D4, 100) };
    f.pop_back();
    CHECK(!readHeader(f).has_value());
    Bytes v{ pcapFile(false, 0xA1B2C3D4, 100) };
    v[4] = 3;
    CHECK(!readHeader(v).has_value());
}
TEST("reading records") {
    for (bool big : { false, true }) {
        Bytes f{ pcapFile(big, 0xA1B2C3D4, 64) };
        addRecord(f, big, 1700000000, 250000, { 1, 2, 3 }, 3);
        addRecord(f, big, 1700000001, 5, Bytes(64, 0xEE), 1514);
        const auto packets{ readPackets(f) };
        CHECK(packets.has_value());
        if (packets) {
            CHECK_EQ(packets->size(), 2u);
            if (packets->size() == 2) {
                CHECK_EQ((*packets)[0].seconds, 1700000000u);
                CHECK_EQ((*packets)[0].fraction, 250000u);
                CHECK((*packets)[0].data == (Bytes{ 1, 2, 3 }));
                CHECK_EQ((*packets)[1].originalLength, 1514u);
                CHECK_EQ((*packets)[1].data.size(), 64u);
            }
        }
    }
    const auto none{ readPackets(pcapFile(false, 0xA1B2C3D4, 64)) };
    CHECK(none.has_value() && none->empty());
}
TEST("damaged records") {
    Bytes f{ pcapFile(false, 0xA1B2C3D4, 64) };
    addRecord(f, false, 1, 0, { 1, 2, 3, 4 }, 4);
    Bytes cut{ f }; cut.pop_back();
    CHECK(!readPackets(cut).has_value());
    Bytes shortHeader{ pcapFile(false, 0xA1B2C3D4, 64) };
    shortHeader.insert(shortHeader.end(), { 1, 2, 3, 4, 5, 6, 7, 8 });
    CHECK(!readPackets(shortHeader).has_value());
    Bytes tooBig{ pcapFile(false, 0xA1B2C3D4, 2) };
    addRecord(tooBig, false, 1, 0, { 1, 2, 3 }, 3);
    CHECK(!readPackets(tooBig).has_value());
    Bytes longerThanOriginal{ pcapFile(false, 0xA1B2C3D4, 64) };
    addRecord(longerThanOriginal, false, 1, 0, { 1, 2, 3 }, 2);
    CHECK(!readPackets(longerThanOriginal).has_value());
    CHECK(!readPackets(Bytes{ 1, 2 }).has_value());
}

